def transform(grid):
    # From the demo, change the detached pair of 1s into 0s.
    out = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])-1):
            if grid[r][c] == 1 and grid[r][c+1] == 1:
                # Only the detached isolated token (not connected to larger 1-shapes).
                def connected(y,x):
                    seen={(y,x)}; stack=[(y,x)]
                    while stack:
                        a,b=stack.pop()
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            aa,bb=a+da,b+db
                            if 0<=aa<len(grid) and 0<=bb<len(grid[0]) and grid[aa][bb]==1 and (aa,bb) not in seen:
                                seen.add((aa,bb));stack.append((aa,bb))
                    return seen
                comp=connected(r,c)
                if len(comp)==2:
                    for y,x in comp: out[y][x]=0
    return out

