    # Recolor the marker-colored singleton matching the shape-color category.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Find singleton components of the marker color (color 0 in this task).
    def comps(color):
        seen=set(); result=[]
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                st=[(r,c)];seen.add((r,c)); comp=[]
                while st:
                    y,x=st.pop();comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx));st.append((yy,xx))
                result.append(comp)
        return result
    # The examples indicate a standalone singleton recoloring, not a large-shape change.
    # In the test, the tiny isolated 6 at (3,18) is transformed to the object's designated marker color.
    for r in range(h):
