def transform(grid):
    out=[row[:] for row in grid]
    # In the examples the isolated singleton in a repeated shape's color is recolored to the marker color.
    h,w=len(grid),len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6 and all(not(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==6) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
                out[r][c]=0
    return out

