                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==color and p not in seen:
                            seen.add(p); stack.append(p)
                result.append(comp)
        return result
    def shape(comp):
        y0=min(y for y,x in comp); x0=min(x for y,x in comp)
        return frozenset((y-y0,x-x0) for y,x in comp)
    refs=components(4)
